-- ============================================================================
-- Mobile Shop ERP — Initial Schema Migration (Phase 0)
-- Database: Supabase Postgres 15
-- Notes:
--   * All tables use UUID v4 PKs (generated by app, not DB) for offline-first sync.
--   * All tables include BaseEntity fields: created_at, updated_at, deleted_at,
--     revision, sync_status, created_by, updated_by.
--   * Soft-delete via deleted_at (no hard deletes in app layer).
--   * RLS enabled on every table; policies defined per role.
--   * Includes pgcrypto for gen_random_uuid() fallback.
-- ============================================================================

-- Required extensions
create extension if not exists "pgcrypto";
create extension if not exists "uuid-ossp";

-- Updated_at trigger function (reusable)
create or replace function public.set_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = timezone('utc', now());
  new.revision = coalesce(old.revision, 0) + 1;
  return new;
end;
$$;

-- Auto-update sync_status to 'pending' when row changes (unless explicitly 'synced')
create or replace function public.mark_pending_sync()
returns trigger
language plpgsql
as $$
begin
  if new.sync_status is distinct from 'synced' then
    new.sync_status = 'pending';
  end if;
  return new;
end;
$$;

-- ============================================================================
-- 1. AUTH & RBAC
-- ============================================================================

create table if not exists public.roles (
  id uuid primary key,
  key text not null unique,
  name text not null,
  description text,
  is_system boolean not null default false,
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now()),
  deleted_at timestamptz,
  revision integer not null default 1,
  sync_status text not null default 'synced',
  created_by uuid,
  updated_by uuid
);

create table if not exists public.permissions (
  id uuid primary key,
  key text not null unique,
  module text not null,
  action text not null,
  description text,
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now()),
  deleted_at timestamptz,
  revision integer not null default 1,
  sync_status text not null default 'synced'
);

create table if not exists public.role_permissions (
  id uuid primary key,
  role_id uuid not null references public.roles(id) on delete cascade,
  permission_id uuid not null references public.permissions(id) on delete cascade,
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now()),
  deleted_at timestamptz,
  revision integer not null default 1,
  sync_status text not null default 'synced',
  unique (role_id, permission_id)
);

create table if not exists public.users (
  id uuid primary key,
  username text not null unique,
  password_hash text,
  pin_hash text,
  full_name text not null,
  email text unique,
  phone text,
  avatar_url text,
  role_id uuid not null references public.roles(id),
  branch_id uuid,
  status text not null default 'active' check (status in ('active','suspended','invited')),
  preferences jsonb not null default '{"theme":"system","language":"ar","sidebarCollapsed":false}'::jsonb,
  last_login_at timestamptz,
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now()),
  deleted_at timestamptz,
  revision integer not null default 1,
  sync_status text not null default 'synced',
  created_by uuid,
  updated_by uuid
);

create table if not exists public.audit_logs (
  id uuid primary key,
  user_id uuid references public.users(id),
  action text not null check (action in ('create','update','delete','restore','login','logout','export','print')),
  entity text not null,
  entity_id uuid,
  before jsonb,
  after jsonb,
  ip_address text,
  user_agent text,
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now()),
  deleted_at timestamptz,
  revision integer not null default 1,
  sync_status text not null default 'synced',
  created_by uuid,
  updated_by uuid
);

-- ============================================================================
-- 2. BRANCHES & SETTINGS
-- ============================================================================

create table if not exists public.branches (
  id uuid primary key,
  name text not null,
  code text not null unique,
  address text,
  phone text,
  email text,
  is_main boolean not null default false,
  is_active boolean not null default true,
  settings jsonb not null default '{"taxRate":14,"currency":"EGP","lowStockThreshold":5}'::jsonb,
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now()),
  deleted_at timestamptz,
  revision integer not null default 1,
  sync_status text not null default 'synced',
  created_by uuid,
  updated_by uuid
);

create table if not exists public.settings (
  id uuid primary key,
  key text not null,
  value jsonb not null,
  category text not null,
  branch_id uuid references public.branches(id) on delete cascade,
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now()),
  deleted_at timestamptz,
  revision integer not null default 1,
  sync_status text not null default 'synced',
  unique (key, branch_id)
);

-- ============================================================================
-- 3. CATALOG (Products, Categories, Devices, Suppliers)
-- ============================================================================

create table if not exists public.categories (
  id uuid primary key,
  name text not null,
  slug text not null unique,
  parent_id uuid references public.categories(id) on delete restrict,
  icon text,
  is_active boolean not null default true,
  sort_order integer not null default 0,
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now()),
  deleted_at timestamptz,
  revision integer not null default 1,
  sync_status text not null default 'synced',
  created_by uuid,
  updated_by uuid
);

create table if not exists public.products (
  id uuid primary key,
  sku text not null unique,
  barcode text,
  name text not null,
  name_ar text,
  category_id uuid references public.categories(id) on delete set null,
  brand text,
  model text,
  description text,
  type text not null default 'standard' check (type in ('standard','imei','service')),
  unit text not null default 'piece',
  cost_price numeric(12,2) not null default 0,
  sale_price numeric(12,2) not null default 0,
  wholesale_price numeric(12,2),
  tax_rate numeric(5,2) not null default 0,
  min_quantity integer not null default 0,
  has_warranty boolean not null default false,
  warranty_days integer not null default 0,
  image_url text,
  is_active boolean not null default true,
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now()),
  deleted_at timestamptz,
  revision integer not null default 1,
  sync_status text not null default 'synced',
  created_by uuid,
  updated_by uuid
);

create index if not exists idx_products_category on public.products(category_id) where deleted_at is null;
create index if not exists idx_products_sku on public.products(sku) where deleted_at is null;
create index if not exists idx_products_barcode on public.products(barcode) where deleted_at is null and barcode is not null;

create table if not exists public.device_units (
  id uuid primary key,
  product_id uuid not null references public.products(id) on delete restrict,
  imei1 text not null,
  imei2 text,
  serial_number text,
  branch_id uuid not null references public.branches(id) on delete restrict,
  status text not null default 'in_stock' check (status in ('in_stock','reserved','sold','returned','defective')),
  cost numeric(12,2) not null default 0,
  sale_price numeric(12,2) not null default 0,
  sale_id uuid,
  received_at timestamptz not null default timezone('utc', now()),
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now()),
  deleted_at timestamptz,
  revision integer not null default 1,
  sync_status text not null default 'synced',
  created_by uuid,
  updated_by uuid
);

create unique index if not exists idx_device_units_imei1 on public.device_units(imei1) where deleted_at is null;
create index if not exists idx_device_units_product on public.device_units(product_id) where deleted_at is null;
create index if not exists idx_device_units_branch_status on public.device_units(branch_id, status) where deleted_at is null;

create table if not exists public.suppliers (
  id uuid primary key,
  name text not null,
  code text not null unique,
  phone text,
  email text,
  address text,
  balance numeric(12,2) not null default 0,
  notes text,
  is_active boolean not null default true,
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now()),
  deleted_at timestamptz,
  revision integer not null default 1,
  sync_status text not null default 'synced',
  created_by uuid,
  updated_by uuid
);

-- ============================================================================
-- 4. INVENTORY
-- ============================================================================

create table if not exists public.inventory_stocks (
  id uuid primary key,
  product_id uuid not null references public.products(id) on delete restrict,
  branch_id uuid not null references public.branches(id) on delete restrict,
  quantity numeric(12,2) not null default 0,
  reserved_quantity numeric(12,2) not null default 0,
  min_quantity numeric(12,2) not null default 0,
  max_quantity numeric(12,2),
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now()),
  deleted_at timestamptz,
  revision integer not null default 1,
  sync_status text not null default 'synced',
  unique (product_id, branch_id)
);

create table if not exists public.stock_movements (
  id uuid primary key,
  product_id uuid not null references public.products(id) on delete restrict,
  branch_id uuid not null references public.branches(id) on delete restrict,
  type text not null check (type in ('purchase','sale','return_in','return_out','transfer_in','transfer_out','adjustment','repair_in','repair_out')),
  quantity numeric(12,2) not null,
  balance_after numeric(12,2) not null,
  reason text,
  ref_type text,
  ref_id uuid,
  user_id uuid not null references public.users(id),
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now()),
  deleted_at timestamptz,
  revision integer not null default 1,
  sync_status text not null default 'synced'
);

create index if not exists idx_stock_movements_product on public.stock_movements(product_id, created_at desc) where deleted_at is null;
create index if not exists idx_stock_movements_branch on public.stock_movements(branch_id, created_at desc) where deleted_at is null;

create table if not exists public.stock_transfers (
  id uuid primary key,
  from_branch_id uuid not null references public.branches(id) on delete restrict,
  to_branch_id uuid not null references public.branches(id) on delete restrict,
  status text not null default 'draft' check (status in ('draft','in_transit','received','canceled')),
  total_items integer not null default 0,
  notes text,
  user_id uuid not null references public.users(id),
  shipped_at timestamptz,
  received_at timestamptz,
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now()),
  deleted_at timestamptz,
  revision integer not null default 1,
  sync_status text not null default 'synced'
);

create table if not exists public.stock_transfer_items (
  id uuid primary key,
  transfer_id uuid not null references public.stock_transfers(id) on delete cascade,
  product_id uuid not null references public.products(id) on delete restrict,
  quantity numeric(12,2) not null,
  received_quantity numeric(12,2) not null default 0,
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now()),
  deleted_at timestamptz,
  revision integer not null default 1,
  sync_status text not null default 'synced'
);

-- ============================================================================
-- 5. CUSTOMERS & SALES
-- ============================================================================

create table if not exists public.customers (
  id uuid primary key,
  name text not null,
  code text,
  phone text,
  email text,
  address text,
  tax_number text,
  balance numeric(12,2) not null default 0,
  credit_limit numeric(12,2) not null default 0,
  notes text,
  is_active boolean not null default true,
  total_purchases numeric(12,2) not null default 0,
  total_repairs integer not null default 0,
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now()),
  deleted_at timestamptz,
  revision integer not null default 1,
  sync_status text not null default 'synced',
  created_by uuid,
  updated_by uuid
);

create index if not exists idx_customers_phone on public.customers(phone) where deleted_at is null and phone is not null;

create table if not exists public.sales (
  id uuid primary key,
  invoice_no text not null unique,
  branch_id uuid not null references public.branches(id) on delete restrict,
  customer_id uuid references public.customers(id) on delete set null,
  cashier_id uuid not null references public.users(id),
  status text not null default 'completed' check (status in ('draft','completed','voided','refunded')),
  subtotal numeric(12,2) not null default 0,
  discount numeric(12,2) not null default 0,
  discount_type text not null default 'amount' check (discount_type in ('amount','percent')),
  tax numeric(12,2) not null default 0,
  total numeric(12,2) not null default 0,
  paid numeric(12,2) not null default 0,
  change numeric(12,2) not null default 0,
  payment_method text not null default 'cash',
  due_amount numeric(12,2) not null default 0,
  notes text,
  completed_at timestamptz,
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now()),
  deleted_at timestamptz,
  revision integer not null default 1,
  sync_status text not null default 'synced'
);

create index if not exists idx_sales_branch_date on public.sales(branch_id, created_at desc) where deleted_at is null;
create index if not exists idx_sales_customer on public.sales(customer_id) where deleted_at is null and customer_id is not null;

create table if not exists public.sale_items (
  id uuid primary key,
  sale_id uuid not null references public.sales(id) on delete cascade,
  product_id uuid not null references public.products(id) on delete restrict,
  device_unit_id uuid references public.device_units(id) on delete set null,
  quantity numeric(12,2) not null,
  unit_price numeric(12,2) not null,
  discount numeric(12,2) not null default 0,
  discount_type text not null default 'amount',
  tax_rate numeric(5,2) not null default 0,
  total numeric(12,2) not null default 0,
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now()),
  deleted_at timestamptz,
  revision integer not null default 1,
  sync_status text not null default 'synced'
);

create table if not exists public.invoices (
  id uuid primary key,
  sale_id uuid references public.sales(id) on delete cascade,
  invoice_no text not null unique,
  type text not null default 'sale' check (type in ('sale','repair','return')),
  pdf_base64 text,
  qr_data text,
  total numeric(12,2) not null default 0,
  tax numeric(12,2) not null default 0,
  issued_at timestamptz not null default timezone('utc', now()),
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now()),
  deleted_at timestamptz,
  revision integer not null default 1,
  sync_status text not null default 'synced'
);

create table if not exists public.invoice_payments (
  id uuid primary key,
  invoice_id uuid not null references public.invoices(id) on delete cascade,
  method text not null,
  amount numeric(12,2) not null,
  reference text,
  paid_at timestamptz not null default timezone('utc', now()),
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now()),
  deleted_at timestamptz,
  revision integer not null default 1,
  sync_status text not null default 'synced'
);

-- ============================================================================
-- 6. RETURNS
-- ============================================================================

create table if not exists public.returns (
  id uuid primary key,
  return_no text not null unique,
  sale_id uuid not null references public.sales(id) on delete restrict,
  branch_id uuid not null references public.branches(id) on delete restrict,
  customer_id uuid references public.customers(id) on delete set null,
  reason text,
  total numeric(12,2) not null default 0,
  status text not null default 'pending' check (status in ('pending','approved','rejected','completed')),
  refund_method text not null default 'cash',
  approved_by uuid references public.users(id),
  approved_at timestamptz,
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now()),
  deleted_at timestamptz,
  revision integer not null default 1,
  sync_status text not null default 'synced'
);

create table if not exists public.return_items (
  id uuid primary key,
  return_id uuid not null references public.returns(id) on delete cascade,
  sale_item_id uuid not null references public.sale_items(id) on delete restrict,
  quantity numeric(12,2) not null,
  refund_amount numeric(12,2) not null,
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now()),
  deleted_at timestamptz,
  revision integer not null default 1,
  sync_status text not null default 'synced'
);

-- ============================================================================
-- 7. REPAIRS
-- ============================================================================

create table if not exists public.repairs (
  id uuid primary key,
  ticket_no text not null unique,
  branch_id uuid not null references public.branches(id) on delete restrict,
  customer_id uuid not null references public.customers(id) on delete restrict,
  technician_id uuid references public.users(id) on delete set null,
  received_by uuid not null references public.users(id),
  device_brand text not null,
  device_model text not null,
  device_imei text,
  device_password text,
  problem_description text not null,
  customer_notes text,
  accessories jsonb not null default '[]'::jsonb,
  inspection_photos jsonb not null default '[]'::jsonb,
  status text not null default 'received' check (status in ('received','diagnosing','waiting_parts','repairing','ready','delivered','canceled','warranty_return')),
  received_at timestamptz not null default timezone('utc', now()),
  estimated_delivery_at timestamptz,
  started_at timestamptz,
  completed_at timestamptz,
  delivered_at timestamptz,
  labor_cost numeric(12,2) not null default 0,
  parts_cost numeric(12,2) not null default 0,
  discount numeric(12,2) not null default 0,
  total numeric(12,2) not null default 0,
  paid numeric(12,2) not null default 0,
  due_amount numeric(12,2) not null default 0,
  warranty_days integer not null default 0,
  parent_repair_id uuid references public.repairs(id) on delete set null,
  notes text,
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now()),
  deleted_at timestamptz,
  revision integer not null default 1,
  sync_status text not null default 'synced'
);

create index if not exists idx_repairs_branch_status on public.repairs(branch_id, status) where deleted_at is null;
create index if not exists idx_repairs_customer on public.repairs(customer_id) where deleted_at is null;
create index if not exists idx_repairs_technician on public.repairs(technician_id, status) where deleted_at is null and technician_id is not null;

create table if not exists public.repair_status_history (
  id uuid primary key,
  repair_id uuid not null references public.repairs(id) on delete cascade,
  from_status text,
  to_status text not null,
  note text,
  user_id uuid not null references public.users(id),
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now()),
  deleted_at timestamptz,
  revision integer not null default 1,
  sync_status text not null default 'synced'
);

create table if not exists public.repair_parts (
  id uuid primary key,
  repair_id uuid not null references public.repairs(id) on delete cascade,
  product_id uuid not null references public.products(id) on delete restrict,
  quantity numeric(12,2) not null,
  unit_price numeric(12,2) not null,
  total numeric(12,2) not null,
  stock_movement_id uuid references public.stock_movements(id) on delete set null,
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now()),
  deleted_at timestamptz,
  revision integer not null default 1,
  sync_status text not null default 'synced'
);

-- ============================================================================
-- 8. FINANCE (Cashbox, Expenses, Revenues, Payment Methods)
-- ============================================================================

create table if not exists public.cashboxes (
  id uuid primary key,
  branch_id uuid not null references public.branches(id) on delete restrict,
  user_id uuid not null references public.users(id) on delete restrict,
  opening_balance numeric(12,2) not null default 0,
  closing_balance numeric(12,2),
  expected_closing numeric(12,2),
  variance numeric(12,2),
  opened_at timestamptz not null default timezone('utc', now()),
  closed_at timestamptz,
  status text not null default 'open' check (status in ('open','closed','forced_closed')),
  notes text,
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now()),
  deleted_at timestamptz,
  revision integer not null default 1,
  sync_status text not null default 'synced'
);

create table if not exists public.cashbox_transactions (
  id uuid primary key,
  cashbox_id uuid not null references public.cashboxes(id) on delete cascade,
  type text not null check (type in ('in','out')),
  amount numeric(12,2) not null,
  payment_method text not null,
  reason text not null,
  ref_type text,
  ref_id uuid,
  user_id uuid not null references public.users(id),
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now()),
  deleted_at timestamptz,
  revision integer not null default 1,
  sync_status text not null default 'synced'
);

create table if not exists public.expense_categories (
  id uuid primary key,
  name text not null,
  icon text,
  is_system boolean not null default false,
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now()),
  deleted_at timestamptz,
  revision integer not null default 1,
  sync_status text not null default 'synced'
