create table if not exists public.expenses (
  id uuid primary key,
  branch_id uuid not null references public.branches(id) on delete restrict,
  category_id uuid not null references public.expense_categories(id) on delete restrict,
  amount numeric(12,2) not null,
  payment_method text not null,
  date date not null,
  note text,
  user_id uuid not null references public.users(id),
  cashbox_id uuid references public.cashboxes(id) on delete set null,
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now()),
  deleted_at timestamptz,
  revision integer not null default 1,
  sync_status text not null default 'synced'
);

create table if not exists public.revenue_categories (
  id uuid primary key,
  name text not null,
  icon text,
  is_system boolean not null default false,
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now()),
  deleted_at timestamptz,
  revision integer not null default 1,
  sync_status text not null default 'synced'
);

create table if not exists public.revenues (
  id uuid primary key,
  branch_id uuid not null references public.branches(id) on delete restrict,
  category_id uuid not null references public.revenue_categories(id) on delete restrict,
  amount numeric(12,2) not null,
  payment_method text not null,
  date date not null,
  note text,
  user_id uuid not null references public.users(id),
  cashbox_id uuid references public.cashboxes(id) on delete set null,
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now()),
  deleted_at timestamptz,
  revision integer not null default 1,
  sync_status text not null default 'synced'
);

create table if not exists public.payment_methods (
  id uuid primary key,
  key text not null unique,
  name text not null,
  name_ar text not null,
  icon text,
  type text not null check (type in ('cash','digital','credit')),
  is_active boolean not null default true,
  sort_order integer not null default 0,
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now()),
  deleted_at timestamptz,
  revision integer not null default 1,
  sync_status text not null default 'synced'
);

-- ============================================================================
-- 9. EMPLOYEES & SHIFTS
-- ============================================================================

create table if not exists public.shifts (
  id uuid primary key,
  name text not null,
  start_time time not null,
  end_time time not null,
  grace_minutes integer not null default 15,
  is_active boolean not null default true,
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now()),
  deleted_at timestamptz,
  revision integer not null default 1,
  sync_status text not null default 'synced'
);

create table if not exists public.employees (
  id uuid primary key,
  user_id uuid references public.users(id) on delete set null,
  branch_id uuid not null references public.branches(id) on delete restrict,
  code text not null,
  full_name text not null,
  national_id text,
  phone text,
  address text,
  hire_date date not null,
  termination_date date,
  status text not null default 'active' check (status in ('active','on_leave','terminated')),
  position text,
  base_salary numeric(12,2) not null default 0,
  allowances numeric(12,2) not null default 0,
  shift_id uuid references public.shifts(id) on delete set null,
  photo_url text,
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now()),
  deleted_at timestamptz,
  revision integer not null default 1,
  sync_status text not null default 'synced',
  created_by uuid,
  updated_by uuid
);

create table if not exists public.attendance (
  id uuid primary key,
  employee_id uuid not null references public.employees(id) on delete cascade,
  branch_id uuid not null references public.branches(id) on delete restrict,
  date date not null,
  check_in timestamptz,
  check_out timestamptz,
  status text not null default 'present' check (status in ('present','absent','late','leave','holiday')),
  notes text,
  created_at timestamptz not null default timezone('utc', now()),
  updated_at timestamptz not null default timezone('utc', now()),
  deleted_at timestamptz,
  revision integer not null default 1,
  sync_status text not null default 'synced'
);

-- ============================================================================
-- 10. TRIGGERS — auto-set updated_at + revision + sync_status
-- ============================================================================

do $$
declare
  tbl text;
begin
  for tbl in
    select unnest(array[
      'roles','permissions','role_permissions','users','audit_logs',
      'branches','settings',
      'categories','products','device_units','suppliers',
      'inventory_stocks','stock_movements','stock_transfers','stock_transfer_items',
      'customers','sales','sale_items','invoices','invoice_payments',
      'returns','return_items',
      'repairs','repair_status_history','repair_parts',
      'cashboxes','cashbox_transactions','expense_categories','expenses',
      'revenue_categories','revenues','payment_methods',
      'shifts','employees','attendance'
    ])
  loop
    execute format(
      'drop trigger if exists trg_%1$s_updated_at on public.%1$s;
       create trigger trg_%1$s_updated_at
         before update on public.%1$s
         for each row execute function public.set_updated_at();',
      tbl
    );
    execute format(
      'drop trigger if exists trg_%1$s_sync_status on public.%1$s;
       create trigger trg_%1$s_sync_status
         before update on public.%1$s
         for each row execute function public.mark_pending_sync();',
      tbl
    );
  end loop;
end $$;

-- ============================================================================
-- 11. ROW LEVEL SECURITY (RLS) — enable on every table
-- ============================================================================

do $$
declare
  tbl text;
begin
  for tbl in
    select unnest(array[
      'roles','permissions','role_permissions','users','audit_logs',
      'branches','settings',
      'categories','products','device_units','suppliers',
      'inventory_stocks','stock_movements','stock_transfers','stock_transfer_items',
      'customers','sales','sale_items','invoices','invoice_payments',
      'returns','return_items',
      'repairs','repair_status_history','repair_parts',
      'cashboxes','cashbox_transactions','expense_categories','expenses',
      'revenue_categories','revenues','payment_methods',
      'shifts','employees','attendance'
    ])
  loop
    execute format('alter table public.%I enable row level security;', tbl);
  end loop;
end $$;

-- Note: RLS policies will be added in a separate migration (Phase 1 - Auth & RBAC)
-- For Phase 0, RLS is enabled but permissive policies are added so dev work proceeds:
-- WARNING: These permissive policies MUST be replaced before production deployment.

do $$
declare
  tbl text;
begin
  for tbl in
    select unnest(array[
      'roles','permissions','role_permissions','users','audit_logs',
      'branches','settings',
      'categories','products','device_units','suppliers',
      'inventory_stocks','stock_movements','stock_transfers','stock_transfer_items',
      'customers','sales','sale_items','invoices','invoice_payments',
      'returns','return_items',
      'repairs','repair_status_history','repair_parts',
      'cashboxes','cashbox_transactions','expense_categories','expenses',
      'revenue_categories','revenues','payment_methods',
      'shifts','employees','attendance'
    ])
  loop
    execute format(
      'drop policy if exists dev_permissive_all on public.%I;
       create policy dev_permissive_all on public.%I
         for all
         using (true)
         with check (true);',
      tbl, tbl
    );
  end loop;
end $$;
